import React from 'react';

const BackgroundEffect = () => {
  return (
    <div className="relative h-screen w-full bg-black">
      <div className="absolute inset-0 bg-gradient-to-r from-gray-900 via-gray-700 to-black opacity-60"></div>
      <div className="absolute left-0 right-0 top-[-10%] h-[1000px] w-[1000px] rounded-full bg-gradient-radial from-white/30 to-transparent"></div>
    </div>
  );
};

export default BackgroundEffect;
